import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

data class TasksUiState(val tasks: List<String> = emptyList(), val loading: Boolean = false)

class TasksViewModel : ViewModel() {
    private val _state = MutableStateFlow(TasksUiState())
    val state: StateFlow<TasksUiState> = _state.asStateFlow()

    fun add(title: String) {
        _state.update { it.copy(tasks = it.tasks + title) }
    }
}

fun main() {
    val vm = TasksViewModel()
    vm.add("Хлеб")
    vm.add("Сыр")
    println(vm.state.value.tasks)
    println(vm.state.value.loading)
}

import androidx.compose.foundation.layout.Column
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue

@Composable
fun CounterScreen(viewModel: CounterViewModel) {
    val count by viewModel.count.collectAsState()
    Column {
        Text("Счёт: $count")
        Button(onClick = { viewModel.increment() }) {
            Text("+1")
        }
    }
}

import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

class CounterViewModel : ViewModel() {
    private val _count = MutableStateFlow(0)
    val count: StateFlow<Int> = _count.asStateFlow()

    fun increment() {
        _count.value += 1
    }
}

fun main() {
    val vm = CounterViewModel()
    vm.increment()
    check(vm.count.value == 1) { "ожидали 1" }
    println("Проверка прошла")
}
